#define PI 3.14159265359

// 円を描画する関数
float drawCircle(vec2 uv, vec2 center, float radius, float thickness) {
    float dist = length(uv - center);
    float outer = smoothstep(radius + 0.002, radius, dist);
    float inner = smoothstep(radius - thickness, radius - thickness - 0.002, dist);
    return outer - inner;
}

    // HSVからRGBへの変換関数
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// 線を描画する関数
float drawLine(vec2 uv, vec2 p1, vec2 p2, float thickness) {
    vec2 dir = p2 - p1;
    vec2 pos = uv - p1;
    float h = clamp(dot(pos, dir) / dot(dir, dir), 0.0, 1.0);
    float dist = length(pos - dir * h);
    return smoothstep(thickness + 0.002, thickness, dist);
}

// スケール値を循環させる関数（1.0から2.0の間）
float cycleScale(float scale) {
    return 1.0 + mod(scale, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);

    float time = iTime * 0.3;  // 全体の時間スケール
    float pattern = 0.0;
    float baseRadius = 0.15;
    float circleSize = 0.08;
    float thickness = 0.004;

    // 各層の回転とズームを計算
    float centerRotation = time * 0.2;  // 中心層の回転（ゆっくり）
    float innerRotation = time * 0.5;   // 内側層の回転（中程度）
    float outerRotation = -time * 0.3;  // 外側層の回転（逆方向）

    float baseScale = exp2(time);  // 指数関数的な変化

    // 各層で異なるスケールを設定（位相をずらす）
    float centerScale = cycleScale(log2(baseScale));
    float innerScale = cycleScale(log2(baseScale) + 0.33);
    float outerScale = cycleScale(log2(baseScale) + 0.66);

    // 円の位置を計算（回転とスケールを組み合わせる）
    vec2[13] circles;

    // 中心の円（centerScaleを使用）
    circles[0] = vec2(0.0) / centerScale;

    // 内側の6つの円（回転とスケールを適用）
    for(int i = 0; i < 6; i++) {
        float angle = float(i) * PI / 3.0 + innerRotation;
        circles[i + 1] = (baseRadius * vec2(cos(angle), sin(angle))) / innerScale;
    }

    // 外側の6つの円（回転とスケールを適用）
    for(int i = 0; i < 6; i++) {
        float angle = float(i) * PI / 3.0 + PI / 6.0 + outerRotation;
        circles[i + 7] = (baseRadius * 2.0 * vec2(cos(angle), sin(angle))) / outerScale;
    }

    // 各層ごとに異なる透明度を設定
    float centerAlpha = smoothstep(1.0, 1.8, centerScale) * smoothstep(2.0, 1.2, centerScale);
    float innerAlpha = smoothstep(1.0, 1.8, innerScale) * smoothstep(2.0, 1.2, innerScale);
    float outerAlpha = smoothstep(1.0, 1.8, outerScale) * smoothstep(2.0, 1.2, outerScale);

    // すべての円を描画（透明度を適用）
    pattern += drawCircle(uv, circles[0], circleSize, thickness) * centerAlpha;

    for(int i = 1; i < 7; i++) {
        pattern += drawCircle(uv, circles[i], circleSize, thickness) * innerAlpha;
    }

    for(int i = 7; i < 13; i++) {
        pattern += drawCircle(uv, circles[i], circleSize, thickness) * outerAlpha;
    }

    // 接続線を描画（透明度を考慮）
    // 中心から内側の円への線
    for(int i = 1; i < 7; i++) {
        pattern += drawLine(uv, circles[0], circles[i], thickness) * min(centerAlpha, innerAlpha);
    }

    // 内側の円同士の接続
    for(int i = 1; i < 7; i++) {
        for(int j = i + 1; j < 7; j++) {
            pattern += drawLine(uv, circles[i], circles[j], thickness) * innerAlpha;
        }
    }

    // 内側の円から外側の円への接続
    for(int i = 1; i < 7; i++) {
        for(int j = 7; j < 13; j++) {
            pattern += drawLine(uv, circles[i], circles[j], thickness) * min(innerAlpha, outerAlpha);
        }
    }

    // 外側の円同士の接続
    for(int i = 7; i < 13; i++) {
        for(int j = i + 1; j < 13; j++) {
            pattern += drawLine(uv, circles[i], circles[j], thickness) * outerAlpha;
        }
    }

    // カラフルな色の設定
    vec3 centerColor = hsv2rgb(vec3(time * 0.1, 0.8, 1.0));              // 時間で変化する色相
    vec3 innerColor = hsv2rgb(vec3(time * 0.1 + 0.33, 0.9, 1.0));       // 位相をずらした色相
    vec3 outerColor = hsv2rgb(vec3(time * 0.1 + 0.66, 0.9, 1.0));       // さらに位相をずらした色相
    vec3 lineColor = hsv2rgb(vec3(time * 0.2, 0.5, 1.0));               // より速く変化する線の色

    // パターンの色を合成
    vec3 color = vec3(0.05, 0.07, 0.1);  // 暗い背景色

    // 各層の色を適用
    color += pattern * mix(centerColor, innerColor, innerAlpha) * 0.7;
    color += pattern * mix(innerColor, outerColor, outerAlpha) * 0.7;

    // 輝き効果の追加（カラフルなグロー）
    float glow = smoothstep(0.1, 1.0, pattern) * 0.5;
    color += glow * mix(centerColor, outerColor, 0.5) * 0.5;

    fragColor = vec4(color, 1.0);
}
